        as.numeric(data[[9]][i] %||% 0),  # other_current_asset_initial_quantity
        as.character(data[[10]][i] %||% NA),  # revaluation_method
        as.numeric(data[[11]][i] %||% 0),  # revalued_amount
        as.numeric(data[[12]][i] %||% 0),  # other_current_asset_revalued_quantity
        as.numeric(data[[13]][i] %||% 0),  # debit
        as.numeric(data[[14]][i] %||% 0),  # other_current_asset_debit_quantity
        as.numeric(data[[15]][i] %||% 0),  # credit
        as.numeric(data[[16]][i] %||% 0),  # other_current_asset_credit_quantity
        as.character(data[[17]][i] %||% NA),  # correspondence_debit
        as.character(data[[18]][i] %||% NA),  # correspondence_credit
        as.numeric(data[[19]][i] %||% 0),  # final_balance
        as.numeric(data[[20]][i] %||% 0)  # other_current_asset_residual_quantity
      ))
    }

      message("Inserted ", nrow(data), " rows for session: ", session_id)
    } else {
      message("No new data to insert for session: ", session_id)
    }

    dbExecute(conn, "COMMIT")
    dbDisconnect(conn)
    message("Successfully saved data for session: ", session_id)
    return(TRUE)

  }, error = function(e) {
    if (!is.null(conn)) {
      try(dbExecute(conn, "ROLLBACK"), silent = TRUE)
      dbDisconnect(conn)
    }
    message("Error in save_general_2990_data: ", e$message)
    return(FALSE)
  })
}

