initialize_2011_1_table <- function(conn) {
  tables <- list(
    app_data_2011_1 = "
      CREATE TABLE IF NOT EXISTS app_data_2011_1 (
        id SERIAL PRIMARY KEY,
        session_id VARCHAR(255) NOT NULL,
        operation_date DATE,
        operation_time TIMESTAMP,
        document_number VARCHAR(255),
	security_type VARCHAR(255),
	security_maturity_period VARCHAR(255),
	operation_description TEXT, 
	initial_accounting_method VARCHAR(255),
	initial_accounting_quantity NUMERIC DEFAULT 0,
	initial_balance NUMERIC DEFAULT 0,
	revaluation_method VARCHAR(255),
	revaluation_quantity NUMERIC DEFAULT 0,
	revalued_amount NUMERIC DEFAULT 0,
	asset_increase_quantity NUMERIC DEFAULT 0,
	debit NUMERIC DEFAULT 0,
	asset_decrease_quantity NUMERIC DEFAULT 0,
	credit NUMERIC DEFAULT 0,
	correspondence_debit VARCHAR(255), 
	correspondence_credit VARCHAR(255), 
	final_balance_quantity NUMERIC DEFAULT 0,
	final_balance NUMERIC DEFAULT 0,
	username VARCHAR(255),
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
      )"
  )

  for (table_name in names(tables)) {
    dbExecute(conn, tables[[table_name]])
  }
  
  index_queries <- list("CREATE INDEX IF NOT EXISTS idx_2011_1_key ON app_data_2011_1 (session_id, operation_date, operation_time, username, updated_at DESC, id DESC)")
  
  for (index_query in index_queries) {
    try(dbExecute(conn, index_query), silent = TRUE)
  }  
  return(TRUE)
}

