ui <- fluidPage(
  tags$head(
    tags$script(HTML("
      $(document).on('shiny:disconnected', function(event) {
        $('#connection-status').html('<span style=\"color: red;\">● Disconnected</span>');
        $('#connection-status').css('background-color', '#ffebee');
      });
      
      $(document).on('shiny:connected', function(event) {
        $('#connection-status').html('<span style=\"color: green;\">● Connected</span>');
        $('#connection-status').css('background-color', '#e8f5e8');
      });
      
      Shiny.addCustomMessageHandler('data_updated', function(message) {
        if (message.session_id === Shiny.shinyapp.$values.session_id) {
          console.log('Данные обновлены, загружаем...');
          Shiny.setInputValue('force_reload', Math.random());
        }
      });
      
      // Обработчик для скачивания файлов
      Shiny.addCustomMessageHandler('downloadFile', function(message) {
        var link = document.createElement('a');
        link.href = message.url;
        link.download = message.filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      });
    ")),
    tags$style(HTML("
      /*  Fixed DashboardHeader */
      .skin-blue .main-header {
        position: fixed !important;
        width: 100%;
        z-index: 1030;
      }
      .skin-blue .main-sidebar {
        padding-top: 50px;
      }
      .content-wrapper, .right-side {
        padding-top: 50px;
      }
      
      /*  Light blue download buttons */
      .btn-download, 
      .btn-download:hover,
      .btn-download:focus,
      .btn-download:active {
        background-color: #add8e6 !important;
        border-color: #add8e6 !important;
        color: #000 !important;
      }
      
      /*  Light green save buttons */
      .btn-save,
      .btn-save:hover,
      .btn-save:focus,
      .btn-save:active {
        background-color: #90ee90 !important;
        border-color: #90ee90 !important;
        color: #000 !important;
      }
      
      .connection-status {
        position: fixed;
        top: 10px;
        right: 10px;
        z-index: 9999;
        background: #e8f5e8;
        padding: 8px 15px;
        border-radius: 5px;
        box-shadow: 0 2px 5px rgba(0,0,0,0.2);
        font-size: 14px;
        font-weight: bold;
        border: 1px solid #4caf50;
      }
      .session-info {
        background: #e3f2fd;
        padding: 10px;
        border-radius: 5px;
        margin: 10px 0;
        border: 1px solid #2196f3;
      }
      .loading-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(255, 255, 255, 0.8);
        z-index: 9999;
        display: flex;
        justify-content: center;
        align-items: center;
        flex-direction: column;
      }
      .auth-status {
        margin-top: 20px;
        padding: 15px;
        border-radius: 5px;
        font-weight: bold;
      }
      .auth-success {
        background-color: #d4edda;
        color: #155724;
        border: 1px solid #c3e6cb;
      }
      .auth-error {
        background-color: #f8d7da;
        color: #721c24;
        border: 1px solid #f5c6cb;
      }
      .auth-warning {
        background-color: #fff3cd;
        color: #856404;
        border: 1px solid #ffeaa7;
      }
      .user-info-box {
        background-color: #e8f5e9;
        border: 1px solid #4caf50;
        border-radius: 5px;
        padding: 15px;
        margin: 10px 0;
      }
      .debit-credit-panel {
        background-color: #f5f5f5;
        border: 1px solid #ddd;
        border-radius: 5px;
        padding: 15px;
        margin: 10px 0;
      }
      .debit-credit-table {
        margin-top: 10px;
        margin-bottom: 20px;
      }
    "))
  ),
  dashboardPage(
    dashboardHeader(
      title = "МСФО",
      tags$li(class = "dropdown",
        tags$div(class = "connection-status", id = "connection-status",
          tags$span(style = "color: green;", "● Connected")
        )
      )
    ),
  dashboardSidebar(
    width = 1050,
    sidebarMenu(
      id = "sidebar",
      menuItem("Главная", tabName = "home", icon = icon("home"),
        menuItem("Авторизация", tabName = "auth"),
        menuItem("Управление данными", tabName = "home_dashboard"),
        menuItem("Загрузка данных", tabName = "data_load")
       ),
        menuItem("Учет", tabName = "Учет",
