	# Удаляет из таблицы БД строки с пустым пользователем для указанной сессии
	delete_empty_user_rows <- function(table_name, session_id) {
	  conn <- NULL
	  tryCatch({
	    conn <- create_database_connection()
	    if (is.null(conn)) return(FALSE)
	    query <- sprintf(
	      "DELETE FROM %s WHERE session_id = $1 AND (username IS NULL OR username = '')",
	      table_name
	    )
	    dbExecute(conn, query, list(session_id))
	    dbDisconnect(conn)
	    return(TRUE)
	  }, error = function(e) {
	    if (!is.null(conn)) dbDisconnect(conn)
	    message("Ошибка при удалении пустых пользователей из ", table_name, ": ", e$message)
	    return(FALSE)
	  })
	}
  
	  output$show_loading <- reactive({
	    r$show_loading
	  })
	  outputOptions(output, "show_loading", suspendWhenHidden = FALSE)
	  
	  output$auth_status_ui <- renderUI({
	    if (!is.null(r$auth_status)) {
	      div(class = paste("auth-status", r$auth_status_type),
	        HTML(r$auth_status)
	      )
	    }
	  })
  
	  update_auth_status <- function(message, type = "success") {
	    r$auth_status <- message
	    r$auth_status_type <- paste0("auth-", type)
	  }
	  
	  reset_auth_status <- function() {
	    r$auth_status <- NULL
	    r$auth_status_type <- NULL
	  }
	  
	  observeEvent(input$username, {
	    req(input$username, input$username != "")
	    
	    reset_auth_status()
	    
	    r$show_loading <- TRUE
	    
	    tryCatch({
	      user_info <- get_or_create_user_simple(input$username, is_new_session = TRUE)
	      
	      if (is.null(user_info)) {
	        update_auth_status("Ошибка при работе с пользователем. Проверьте подключение к базе данных.", "error")
	      } else {
	        r$current_user_data <- user_info
	        
	        if (user_info$is_new && !is.null(user_info$password)) {
	          updateTextInput(session, "password", value = user_info$password)
	          update_auth_status(paste("Создан новый пользователь", input$username, ". Пароль показан выше."), "success")
	        } else {
	          updateTextInput(session, "password", value = "")
	          update_auth_status(paste("Данные пользователя", input$username, "успешно загружены. Введите пароль для авторизации."), "success")
	        }
	      }
	    }, error = function(e) {
	      message("Ошибка при работе с пользователем: ", e$message)
	      update_auth_status(paste("Ошибка: ", e$message), "error")
	    }, finally = {
	      r$show_loading <- FALSE
	    })
	  })
	  
	  observeEvent(input$login, {
	    req(input$username, input$username != "", input$password)
    
	    if (is.null(r$current_user_data)) {
	      update_auth_status("Сначала выберите пользователя для загрузки данных.", "warning")
	      return()
	    }
    
	    r$show_loading <- TRUE
    
	    tryCatch({
	      if (check_user_password(input$username, input$password)) {
	        r$user_authenticated <- TRUE
	        r$current_user <- input$username
	        update_auth_status(paste("Пользователь", input$username, "успешно авторизован!"), "success")
	      } else {
	        update_auth_status("Имя пользователя и пароль не совпадают.", "error")
	      }
	    }, error = function(e) {
	      message("Ошибка при проверке пароля: ", e$message)
	      update_auth_status("Ошибка при проверке пароля. Попробуйте снова.", "error")
	    }, finally = {
	      r$show_loading <- FALSE
	    })
	  })
  
	  observeEvent(input$debit_select, {
	    req(input$debit_select != "")

	  r$debit_account_selected <- input$debit_select

	    if (input$debit_select == "2011.1") {
	      r$debit_table_data <- copy(DF2011.1)
	    } else if (input$debit_select == "2011.2") {
	      r$debit_table_data <- copy(DF2011.2)
	    } else if (input$debit_select == "2011.3") {
	      r$debit_table_data <- copy(DF2011.3)
	    } else if (input$debit_select == "2011.4") {
	      r$debit_table_data <- copy(DF2011.4)
	    } else if (input$debit_select == "2012.1") {
	      r$debit_table_data <- copy(DF2012.1)
	    } else if (input$debit_select == "2012.2") {
	      r$debit_table_data <- copy(DF2012.2)
	    } else if (input$debit_select == "2012.3") {
	      r$debit_table_data <- copy(DF2012.3)
	    } else if (input$debit_select == "2012.4") {
	      r$debit_table_data <- copy(DF2012.4)
	    } else if (input$debit_select == "2012.5") {
	      r$debit_table_data <- copy(DF2012.5)
	    } else if (input$debit_select == "2021.1") {
	      r$debit_table_data <- copy(DF2021.1)
	    } else if (input$debit_select == "2021.2") {
	      r$debit_table_data <- copy(DF2021.2)
	    } else if (input$debit_select == "2021.3") {
	      r$debit_table_data <- copy(DF2021.3)
	    } else if (input$debit_select == "2022.1") {
	      r$debit_table_data <- copy(DF2022.1)
	    } else if (input$debit_select == "2022.2") {
	      r$debit_table_data <- copy(DF2022.2)
	    } else if (input$debit_select == "2022.3") {
	      r$debit_table_data <- copy(DF2022.3)
	    } else if (input$debit_select == "2022.4") {
	      r$debit_table_data <- copy(DF2022.4)
	    } else if (input$debit_select == "2023.1") {
	      r$debit_table_data <- copy(DF2023.1)
	    } else if (input$debit_select == "2023.2") {
	      r$debit_table_data <- copy(DF2023.2)
