    			credit_row[, `Сальдо конечное` := `Сальдо начальное` + `Дебет` - `Кредит`]
    			credit_row[, Пользователь := r$current_user]
    
    	if (nrow(data$df2990) > 0) {
      		is_duplicate <- any(sapply(1:nrow(data$df2990), function(i) {
        	all(as.character(credit_row[1, ]) == as.character(data$df2990[i, ]), na.rm = TRUE)
      	}))
      
      	if (!is_duplicate) {
        	data$df2990 <- rbindlist(list(data$df2990, credit_row), use.names = TRUE, fill = TRUE)
        	message("Добавлена новая строка в df2990 из таблицы Кредит")
      	} else {
        	message("Строка уже существует в df2990, не добавляем дубликат")
      	}
    	} else {
      	data$df2990 <- credit_row
      }
     }
    }

