# Обработчик сохранения таблицы 2011.1
observeEvent(input$save_table2011_1, {
  if (!r$user_authenticated) {
    shinyalert("Ошибка", "Для сохранения необходимо авторизоваться.", type = "error")
    return()
  }
  
  if (!r$db_initialized) {
    shinyalert("Ошибка", "База данных недоступна. Невозможно сохранить таблицу.", type = "error")
    return()
  }
  
  current_session <- session_id()
  
  #Обновляем локальные данные из UI-таблицы
  if (!is.null(input$table2011_1Item1)) {
    tryCatch({
      new_df <- hot_to_r(input$table2011_1Item1)
      validation_result <- validate_operation_dates(new_df)
      if (!validation_result$valid) {
        data$df2011.1 <- validation_result$df
      } else {
        data$df2011.1 <- new_df
      }
    }, error = function(e) {
      message("Ошибка при обновлении данных из таблицы 2011.1: ", e$message)
    })
  }
  
  # Удаляем из БД все строки с пустым пользователем для текущей сессии
  delete_empty_user_rows("app_data_2011_1", current_session)
  
  #Фильтруем строки, принадлежащие ТОЛЬКО текущему пользователю
  user_df <- data$df2011.1[data$df2011.1$Пользователь == r$current_user, ]
  
  #Сохраняем данные текущего пользователя
  success <- save_data_simple(user_df, "app_data_2011_1", current_session, r$current_user)
  
  if (success) {
    shinyalert("Успех", paste("Данные таблицы 2011.1 сохранены для пользователя", r$current_user), type = "success")
    r$data_version <- r$data_version + 1
    
    update_info <- get_last_update(current_session)
    if (!is.null(update_info)) {
      r$current_session_last_update <- update_info$timestamp
    }
  } else {
    shinyalert("Ошибка", "Не удалось сохранить данные таблицы 2011.1.", type = "error")
  }
})


