#ОСВ: 2000

observeEvent(input$dates2000, {
    start <- ymd(input$dates2000[[1]])
    end <- ymd(input$dates2000[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2000", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2000[[1]]
      r$end <- input$dates2000[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2000",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

#ОСВ: 2000 to compile 2010

observe({
    if (!any(is.na(input$dates2000))) {
      from=as.Date(input$dates2000[1L])
      to=as.Date(input$dates2000[2L])
      if (from>to) to = from
      selectdates2011_1_1 <- seq.Date(from=from,
                               to=to, by = "day")
     data$df2011.1_4 <- data$df2011.1[as.Date(data$df2011.1$`Дата операции`) %in% selectdates2011_1_1, ]
    } else {
      selectdates2011_1_2 <- unique(as.Date(data$df2011.1$`Дата операции`))
      data$df2011.1_4 <- data$df2011.1[data$df2011.1$`Дата операции` %in% selectdates2011_1_2, ]
