#2011.1

observeEvent(input$dates2011_1, {
    start <- ymd(input$dates2011_1[[1]])
    end <- ymd(input$dates2011_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2011_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2011_1[[1]]
      r$end <- input$dates2011_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2011_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2011_1Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2011.1 <- hot_to_r(input$table2011_1Item1)

    if (!any(is.na(input$dates2011_1)) && input$choices2011_1 == "Выбор по дате операции") {
     	from=as.Date(input$dates2011_1[1L])
      	to=as.Date(input$dates2011_1[2L])
      	if (from>to) to = from
      	selectdates2011_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2011.1_2 <- data$df2011.1[as.Date(data$df2011.1$"Дата операции") %in% selectdates2011_1_1, ]
    } else if (!is.null(input$text) && input$choices2011_1 == "Выбор по учетному номеру") {
      	data$df2011.1_2 <- data$df2011.1[data$df2011.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2011_1 == "Выбор вида ценной бумаги") {
