observeEvent(input$dates2012_1, {
    start <- ymd(input$dates2012_1[[1]])
    end <- ymd(input$dates2012_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2012_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2012_1[[1]]
      r$end <- input$dates2012_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2012_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
}, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2012_1Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2012.1 <- hot_to_r(input$table2012_1Item1)

    if (!any(is.na(input$dates2012_1)) && input$choices2012_1 == "Выбор по дате операции") {
     	from=as.Date(input$dates2012_1[1L])
      	to=as.Date(input$dates2012_1[2L])
      	if (from>to) to = from
      	selectdates2012_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2012.1_2 <- data$df2012.1[as.Date(data$df2012.1$"Дата операции") %in% selectdates2012_1_1, ]
    } else if (!is.null(input$text) && input$choices2012_1 == "Выбор по учетному номеру") {
      	data$df2012.1_2 <- data$df2012.1[data$df2012.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2012_1) && !any(is.na(input$dates2012_1)) && !is.null(input$text) && input$choices2012_1 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2012_1[1L])
      	to=as.Date(input$dates2012_1[2L])
      	if (from>to) to = from
      	selectdates2012_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2012.1_2 <- data$df2012.1[as.Date(data$df2012.1$"Дата операции") %in% selectdates2012_1_2 & data$df2012.1$"Учетный номер" == input$text, ]
    } else {
        selectdates2012_1_3 <- unique(data$df2012.1$"Дата операции")
        data$df2012.1_2 <- data$df2012.1[data$df2012.1$"Дата операции" %in% selectdates2012_1_3, ]
    }
}
})  

  output$table2012_1Item1 <- renderRHandsontable({
    
    data$df2012.1[, `Сальдо конечное` := ifelse(!is.na(data$df2012.1[[9]]) & data$df2012.1[[9]] != 0,
							data$df2012.1[[9]], data$df2012.1[[7]] + data$df2012.1[[10]] - data$df2012.1[[11]])]

    rhandsontable(data$df2012.1, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
