#2032.1

observeEvent(input$dates2032_1, {
    start <- ymd(input$dates2032_1[[1]])
    end <- ymd(input$dates2032_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2032_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2032_1[[1]]
      r$end <- input$dates2032_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2032_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
  }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2032_1Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2032.1 <- hot_to_r(input$table2032_1Item1)

    if (!any(is.na(input$dates2032_1)) && input$choices2032_1 == "Выбор по дате операции") {
     	from=as.Date(input$dates2032_1[1L])
      	to=as.Date(input$dates2032_1[2L])
      	if (from>to) to = from
      	selectdates2032_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2032.1_2 <- data$df2032.1[as.Date(data$df2032.1$"Дата операции") %in% selectdates2032_1_1, ]
    } else if (!is.null(input$text) && input$choices2032_1 == "Выбор по учетному номеру") {
      	data$df2032.1_2 <- data$df2032.1[data$df2032.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2032_1) && !any(is.na(input$dates2032_1)) && !is.null(input$text) && input$choices2032_1 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2032_1[1L])
      	to=as.Date(input$dates2032_1[2L])
      	if (from>to) to = from
      	selectdates2032_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2032.1_2 <- data$df2032.1[as.Date(data$df2032.1$"Дата операции") %in% selectdates2032_1_2 & data$df2032.1$"Учетный номер" == input$text, ]
    } else {
        selectdates2032_1_3 <- unique(data$df2032.1$"Дата операции")
        data$df2032.1_2 <- data$df2032.1[data$df2032.1$"Дата операции" %in% selectdates2032_1_3, ]
    }
   }
  })  

  output$table2032_1Item1 <- renderRHandsontable({
    
    data$df2032.1[, `Сальдо конечное` := ifelse(!is.na(data$df2032.1[[9]]) & data$df2032.1[[9]] != 0,
							data$df2032.1[[9]], data$df2032.1[[7]] + data$df2032.1[[10]] - data$df2032.1[[11]])]

    rhandsontable(data$df2032.1, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
      hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })
  
  output$nested_ui2032_1 <- renderUI({
    if (input$choices2032_1 == "Выбор по дате операции") {
      	dateRangeInput("dates2032_1", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2032_1 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите Учетный номер:")
    } else if (input$choices2032_1 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2032_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите Учетный номер:")
      )
    } 
  })

  output$table2032_1Item2 <- renderRHandsontable({
    rhandsontable(data$df2032.1_2, colWidths = 150, height = 500, readOnly=TRUE,  
		contextMenu = FALSE, manualColumnResize = TRUE, dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")
  })

  output$download_df2032.1 <- downloadHandler(
    filename = function() { "df2032.1.xlsx" },
    content = function(file) {
      write.xlsx(data$df2032.1, file)
    })

