 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2041_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2041_1[[1]]
      r$end <- input$dates2041_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2041_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

          observe({ 
            if (!is.null(input$table2041_1Item1)) {
              if (!r$user_authenticated) {
                update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
                return()
              }
              
              data$df2041.1 <- hot_to_r(input$table2041_1Item1)

    if (!any(is.na(input$dates2041_1)) && input$choices2041_1 == "Выбор по дате операции") {
     	from=as.Date(input$dates2041_1[1L])
      	to=as.Date(input$dates2041_1[2L])
      	if (from>to) to = from
      	selectdates2041_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2041.1_2 <- data$df2041.1[as.Date(data$df2041.1$"Дата операции") %in% selectdates2041_1_1, ]
    } else if (!is.null(input$text) && input$choices2041_1 == "Выбор по учетному номеру") {
      	data$df2041.1_2 <- data$df2041.1[data$df2041.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2041_1 == "Выбор вида производного инструмента") {
      	data$df2041.1_2 <- data$df2041.1[data$df2041.1$"Вид производного инструмента" == input$text, ]
    } else if (!is.null(input$dates2041_1) && !any(is.na(input$dates2041_1)) && !is.null(input$text) && input$choices2041_1 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2041_1[1L])
      	to=as.Date(input$dates2041_1[2L])
      	if (from>to) to = from
      	selectdates2041_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2041.1_2 <- data$df2041.1[as.Date(data$df2041.1$"Дата операции") %in% selectdates2041_1_2 & data$df2041.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2041_1) && !any(is.na(input$dates2041_1)) && !is.null(input$text) && input$choices2041_1 == "Выбор по дате операции и виду производного инструмента") {
     	from=as.Date(input$dates2041_1[1L])
      	to=as.Date(input$dates2041_1[2L])
      	if (from>to) to = from
      	selectdates2041_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2041.1_2 <- data$df2041.1[as.Date(data$df2041.1$"Дата операции") %in% selectdates2041_1_3 & data$df2041.1$"Вид производного инструмента" == input$text, ]
    } else {
        selectdates2041_1_4 <- unique(data$df2041.1$"Дата операции")
        data$df2041.1_2 <- data$df2041.1[data$df2041.1$"Дата операции" %in% selectdates2041_1_4, ]
    }
