#2042.1

observeEvent(input$dates2042_1, {
    start <- ymd(input$dates2042_1[[1]])
    end <- ymd(input$dates2042_1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2042_1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2042_1[[1]]
      r$end <- input$dates2042_1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2042_1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

          observe({ 
            if (!is.null(input$table2042_1Item1)) {
              if (!r$user_authenticated) {
                update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
                return()
              }
              
              data$df2042.1 <- hot_to_r(input$table2042_1Item1)

    if (!any(is.na(input$dates2042_1)) && input$choices2042_1 == "Выбор по дате операции") {
     	from=as.Date(input$dates2042_1[1L])
      	to=as.Date(input$dates2042_1[2L])
      	if (from>to) to = from
      	selectdates2042_1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2042.1_2 <- data$df2042.1[as.Date(data$df2042.1$"Дата операции") %in% selectdates2042_1_1, ]
    } else if (!is.null(input$text) && input$choices2042_1 == "Выбор по учетному номеру") {
      	data$df2042.1_2 <- data$df2042.1[data$df2042.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2042_1 == "Выбор вида производного инструмента") {
      	data$df2042.1_2 <- data$df2042.1[data$df2042.1$"Вид производного инструмента" == input$text, ]
    } else if (!is.null(input$dates2042_1) && !any(is.na(input$dates2042_1)) && !is.null(input$text) && input$choices2042_1 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2042_1[1L])
      	to=as.Date(input$dates2042_1[2L])
      	if (from>to) to = from
      	selectdates2042_1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2042.1_2 <- data$df2042.1[as.Date(data$df2042.1$"Дата операции") %in% selectdates2042_1_2 & data$df2042.1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2042_1) && !any(is.na(input$dates2042_1)) && !is.null(input$text) && input$choices2042_1 == "Выбор по дате операции и виду производного инструмента") {
     	from=as.Date(input$dates2042_1[1L])
      	to=as.Date(input$dates2042_1[2L])
      	if (from>to) to = from
      	selectdates2042_1_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2042.1_2 <- data$df2042.1[as.Date(data$df2042.1$"Дата операции") %in% selectdates2042_1_3 & data$df2042.1$"Вид производного инструмента" == input$text, ]
    } else {
        selectdates2042_1_4 <- unique(data$df2042.1$"Дата операции")
        data$df2042.1_2 <- data$df2042.1[data$df2042.1$"Дата операции" %in% selectdates2042_1_4, ]
    }
   }
  })  

  output$table2042_1Item1 <- renderRHandsontable({
    
   	data$df2042.1[, `Сальдо конечное` := ifelse(!is.na(data$df2042.1[[9]]) & data$df2042.1[[9]] != 0,
							data$df2042.1[[9]], data$df2042.1[[7]] + data$df2042.1[[10]] - data$df2042.1[[11]])]

	rhandsontable(data$df2042.1, colWidths = 150, height = 500, 
                         allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                         contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
              hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
              hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })
  
  output$nested_ui2042_1 <- renderUI({
    if (input$choices2042_1 == "Выбор по дате операции") {
      	dateRangeInput("dates2042_1", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2042_1 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите Учетный номер:")
    } else if (input$choices2042_1 == "Выбор вида производного инструмента") {
      	textInput("text", "Укажите вид производного инструмента:")
    } else if (input$choices2042_1 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2042_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите Учетный номер:")
      )
    } else if (input$choices2042_1 == "Выбор по дате операции и виду производного инструмента") {
      fluidRow(
       	dateRangeInput("dates2042_1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите вид производного инструмента:")
      )
    }
  })

  output$table2042_1Item2 <- renderRHandsontable({
    rhandsontable(data$df2042.1_2, colWidths = 150, height = 300, readOnly=TRUE,   
                contextMenu = FALSE, manualColumnResize = TRUE, dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")
  })

  output$download_df2042.1 <- downloadHandler(
    filename = function() { "df2042.1.xlsx" },
    content = function(file) {
      write.xlsx(data$df2042.1, file)
    })

  output$download_df2042.1_2 <- downloadHandler(
    filename = function() { "df2042.1_2.xlsx" },
    content = function(file) {
      write.xlsx(data$df2042.1_2, file)
    })

