    end <- ymd(input$dates2100[[2]])

 tryCatch({
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2100", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2100[[1]]
      r$end <- input$dates2100[[2]]
      }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2100",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
 }, ignoreInit = TRUE)

