#2110

observeEvent(input$dates2110, {
    start <- ymd(input$dates2110[[1]])
    end <- ymd(input$dates2110[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2110", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2110[[1]]
      r$end <- input$dates2110[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2110",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
  }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2110Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2110 <- hot_to_r(input$table2110Item1)

    if (!any(is.na(input$dates2110)) && input$choices2110 == "Выбор по дате операции") {
     	from=as.Date(input$dates2110[1L])
      	to=as.Date(input$dates2110[2L])
      	if (from>to) to = from
      	selectdates2110_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2110_2 <- data$df2110[as.Date(data$df2110$"Дата операции") %in% selectdates2110_1, ]
    } else if (!is.null(input$text) && input$choices2110 == "Выбор по учетному номеру") {
      	data$df2110_2 <- data$df2110[data$df2110$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2110 == "Выбор вида (названия) товаров или услуг по дебиторской задолженности") {
      	data$df2110_2 <- data$df2110[data$df2110$"Вид (название) товаров или услуг по дебиторской задолженности" == input$text, ]
    } else if (!is.null(input$dates2110) && !any(is.na(input$dates2110)) && !is.null(input$text) && input$choices2110 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2110[1L])
      	to=as.Date(input$dates2110[2L])
      	if (from>to) to = from
      	selectdates2110_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2110_2 <- data$df2110[as.Date(data$df2110$"Дата операции") %in% selectdates2110_2 & data$df2110$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2110) && !any(is.na(input$dates2110)) && !is.null(input$text) && input$choices2110 == "Выбор по дате операции и виду (названию) товаров или услуг по дебиторской задолженности") {
     	from=as.Date(input$dates2110[1L])
      	to=as.Date(input$dates2110[2L])
      	if (from>to) to = from
      	selectdates2110_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2110_2 <- data$df2110[as.Date(data$df2110$"Дата операции") %in% selectdates2110_3 & data$df2110$"Вид (название) товаров или услуг по дебиторской задолженности" == input$text, ]
    } else {
        selectdates2110_4 <- unique(data$df2110$"Дата операции")
        data$df2110_2 <- data$df2110[data$df2110$"Дата операции" %in% selectdates2110_4, ]
    }
   }
  })  

  output$table2110Item1 <- renderRHandsontable({
    
   data$df2110[, `Сальдо конечное` := ifelse(!is.na(data$df2110[[11]]) & data$df2110[[11]] != 0,
						data$df2110[[11]], data$df2110[[8]] + data$df2110[[13]] - data$df2110[[15]])]

    rhandsontable(data$df2110, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
      hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })
  
  output$nested_ui2110 <- renderUI({
    if (input$choices2110 == "Выбор по дате операции") {
      	dateRangeInput("dates2110", "Выберите период времени:", format="yyyy-mm-dd",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2110 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите Учетный номер:")
    } else if (input$choices2110 == "Выбор вида (названия) товаров или услуг по дебиторской задолженности") {
      	textInput("text", "Укажите вид (название) товаров или услуг по дебиторской задолженности:")
    } else if (input$choices2110 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2110", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите Учетный номер:")
      )
    } else if (input$choices2110 == "Выбор по дате операции и виду (названию) товаров или услуг по дебиторской задолженности") {
      fluidRow(
       	dateRangeInput("dates2110", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите вид (название) товаров или услуг по дебиторской задолженности:")
      )}
  })

  output$table2110Item2 <- renderRHandsontable({
    rhandsontable(data$df2110_2, colWidths = 150, height = 500, readOnly=TRUE, 
		contextMenu = FALSE, manualColumnResize = TRUE, dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")
  })

  output$download_df2110 <- downloadHandler(
    filename = function() { "df2110.xlsx" },
    content = function(file) { write.xlsx(data$df2110, file) })

  output$download_df2110_2 <- downloadHandler(
    filename = function() { "df2110_2.xlsx" },
    content = function(file) {  write.xlsx(data$df2110_2, file) })

