observeEvent(input$dates2210, {
    start <- ymd(input$dates2210[[1]])
    end <- ymd(input$dates2210[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2210", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2210[[1]]
      r$end <- input$dates2210[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2210",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2210Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2210 <- hot_to_r(input$table2210Item1)

    if (!any(is.na(input$dates2210)) && input$choices2210 == "Выбор по дате операции") {
     	from=as.Date(input$dates2210[1L])
      	to=as.Date(input$dates2210[2L])
      	if (from>to) to = from
      	selectdates2210_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2210_2 <- data$df2210[as.Date(data$df2210$"Дата операции") %in% selectdates2210_1, ]
    } else if (!is.null(input$text) && input$choices2210 == "Выбор по учетному номеру") {
      	data$df2210_2 <- data$df2210[data$df2210$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2210 == "Выбор вида инвестированных активов") {
      	data$df2210_2 <- data$df2210[data$df2210$"Вид инвестированных активов" == input$text, ]
    } else if (!is.null(input$dates2210) && !any(is.na(input$dates2210)) && !is.null(input$text) && input$choices2210 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2210[1L])
      	to=as.Date(input$dates2210[2L])
      	if (from>to) to = from
      	selectdates2210_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2210_2 <- data$df2210[as.Date(data$df2210$"Дата операции") %in% selectdates2210_2 & data$df2210$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2210) && !any(is.na(input$dates2210)) && !is.null(input$text) && input$choices2210 == "Выбор по дате операции и виду инвестированных активов") {
     	from=as.Date(input$dates2210[1L])
      	to=as.Date(input$dates2210[2L])
      	if (from>to) to = from
      	selectdates2210_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2210_2 <- data$df2210[as.Date(data$df2210$"Дата операции") %in% selectdates2210_3 & data$df2210$"Вид инвестированных активов" == input$text, ]
    } else {
        selectdates2210_4 <- unique(data$df2210$"Дата операции")
        data$df2210_2 <- data$df2210[data$df2210$"Дата операции" %in% selectdates2210_4, ]
    }
   }
  })  

