        Сумма5 = sum(`Конечное сальдо оценочного резерва`[.N], na.rm = TRUE)
      ), by="Учетный номер"][, .(
        `Начальное сальдо оценочного резерва` = sum(Сумма0),
        `Сумма убытков от фактического обесценения` = sum(Сумма1),
        `Сумма ожидаемых убытков` = sum(Сумма2),
        Кредит = sum(Сумма3),
        Дебет = sum(Сумма4),
        `Конечное сальдо оценочного резерва` = sum(Сумма5)
    )]
  } else {
    data$df2300_3[5, 2:7] <- 0
  }
})

observe({ data$df2300_3[6, 2:7] <- data$df2300_3[, .SD[1:5, lapply(.SD, sum)], .SDcols = 2:7] })

