observeEvent(input$dates2411, {
    start <- ymd(input$dates2411[[1]])
    end <- ymd(input$dates2411[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2411", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2411[[1]]
      r$end <- input$dates2411[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2411",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2411Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2411 <- hot_to_r(input$table2411Item1) 

    if (!any(is.na(input$dates2411)) && input$choices2411 == "Выбор по дате операции") {
     	from=as.Date(input$dates2411[1L])
      	to=as.Date(input$dates2411[2L])
      	if (from>to) to = from
      	selectdates2411_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2411_2 <- data$df2411[as.Date(data$df2411$"Дата операции") %in% selectdates2411_1, ]
    } else if (!is.null(input$text) && input$choices2411 == "Выбор по учетному номеру") {
      	data$df2411_2 <- data$df2411[data$df2411$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2411 == "Выбор кадастрового номера земельного участка") {
      	data$df2411_2 <- data$df2411[data$df2411$"Кадастровый номер земельного участка" == input$text, ]
    } else if (!is.null(input$dates2411) && !any(is.na(input$dates2411)) && !is.null(input$text) && input$choices2411 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2411[1L])
      	to=as.Date(input$dates2411[2L])
      	if (from>to) to = from
      	selectdates2411_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2411_2 <- data$df2411[as.Date(data$df2411$"Дата операции") %in% selectdates2411_2 & data$df2411$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2411) && !any(is.na(input$dates2411)) && !is.null(input$text) && input$choices2411 == "Выбор по дате операции и кадастровому номеру земельного участка") {
     	from=as.Date(input$dates2411[1L])
      	to=as.Date(input$dates2411[2L])
      	if (from>to) to = from
      	selectdates2411_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2411_2 <- data$df2411[as.Date(data$df2411$"Дата операции") %in% selectdates2411_3 & data$df2411$"Кадастровый номер земельного участка" == input$text, ]
    } else {
        selectdates2411_4 <- unique(data$df2411$"Дата операции")
        data$df2411_2 <- data$df2411[data$df2411$"Дата операции" %in% selectdates2411_4, ]
    }
   }
  })  

