      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

  observe({
    if (!is.null(input$table2421Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2421 <- hot_to_r(input$table2421Item1)

    if (!any(is.na(input$dates2421)) && input$choices2421 == "Выбор по дате операции") {
     	from=as.Date(input$dates2421[1L])
      	to=as.Date(input$dates2421[2L])
      	if (from>to) to = from
      	selectdates2421_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2421_2 <- data$df2421[as.Date(data$df2421$"Дата операции") %in% selectdates2421_1, ]
    } else if (!is.null(input$text2421) && input$choices2421 == "Выбор по учетному номеру") {
      	data$df2421_2 <- data$df2421[data$df2421$"Учетный номер" == input$text2421, ]
    } else if (!is.null(input$dates2421) && !any(is.na(input$dates2421)) && !is.null(input$text2421) && input$choices2421 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2421[1L])
      	to=as.Date(input$dates2421[2L])
      	if (from>to) to = from
      	selectdates2421_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2421_2 <- data$df2421[as.Date(data$df2421$"Дата операции") %in% selectdates2421_2 & data$df2421$"Учетный номер" == input$text2421, ]
    } else {
        selectdates2421_4 <- unique(data$df2421$"Дата операции")
        data$df2421_2 <- data$df2421[data$df2421$"Дата операции" %in% selectdates2421_4, ]
    }
   }
  })  

  output$table2421Item1 <- renderRHandsontable({

