#2451

observeEvent(input$dates2451, {
    start <- ymd(input$dates2451[[1]])
    end <- ymd(input$dates2451[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2451", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2451[[1]]
      r$end <- input$dates2451[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2451",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

  observe({
    if (!is.null(input$table2451Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2451 <- hot_to_r(input$table2451Item1)

    if (!any(is.na(input$dates2451)) && input$choices2451 == "Выбор по дате операции") {
     	from=as.Date(input$dates2451[1L])
      	to=as.Date(input$dates2451[2L])
      	if (from>to) to = from
      	selectdates2451_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2451_2 <- data$df2451[as.Date(data$df2451$"Дата операции") %in% selectdates2451_1, ]
    } else if (!is.null(input$text2451) && input$choices2451 == "Выбор по учетному номеру") {
      	data$df2451_2 <- data$df2451[data$df2451$"Учетный номер" == input$text2451, ]
    } else if (!is.null(input$dates2451) && !any(is.na(input$dates2451)) && !is.null(input$text2451) && input$choices2451 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2451[1L])
      	to=as.Date(input$dates2451[2L])
      	if (from>to) to = from
      	selectdates2451_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2451_2 <- data$df2451[as.Date(data$df2451$"Дата операции") %in% selectdates2451_2 & data$df2451$"Учетный номер" == input$text2451, ]
    } else {
        selectdates2451_4 <- unique(data$df2451$"Дата операции")
        data$df2451_2 <- data$df2451[data$df2451$"Дата операции" %in% selectdates2451_4, ]
    }
   }
  })  

  output$table2451Item1 <- renderRHandsontable({

	data$df2451[, `Конечное сальдо амортизации` := `Начальное сальдо амортизации` - `Дебет` + `Кредит`]

    rhandsontable(data$df2451, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
      hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })
  
  output$nested_ui2451 <- renderUI({
    if (input$choices2451 == "Выбор по дате операции") {
      	dateRangeInput("dates2451", "Выберите период времени:",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2451 == "Выбор по учетному номеру") {
      	textInput("text2451", "Укажите Учетный номер:")
    } else if (input$choices2451 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2451", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text2451", "Укажите Учетный номер:")
      )
    }
  })

  output$table2451Item2 <- renderRHandsontable({
    rhandsontable(data$df2451_2, colWidths = 150, height = 500, readOnly=TRUE,  
		contextMenu = FALSE, manualColumnResize = TRUE, dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")
  })

  output$download_df2451 <- downloadHandler(
    filename = function() { "df2451.xlsx" },
    content = function(file) { write.xlsx(data$df2451, file) })

  output$download_df2451_2 <- downloadHandler(
    filename = function() { "df2451_2.xlsx" },
    content = function(file) { write.xlsx(data$df2451_2, file) })

