observeEvent(input$dates2510, {
    start <- ymd(input$dates2510[[1]])
    end <- ymd(input$dates2510[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2510", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2510[[1]]
      r$end <- input$dates2510[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2510",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2510Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2510 <- hot_to_r(input$table2510Item1)  

    if (!any(is.na(input$dates2510)) && input$choices2510 == "Выбор по дате операции") {
     	from=as.Date(input$dates2510[1L])
      	to=as.Date(input$dates2510[2L])
      	if (from>to) to = from
      	selectdates2510_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2510_2 <- data$df2510[as.Date(data$df2510$"Дата операции") %in% selectdates2510_1, ]
    } else if (!is.null(input$text) && input$choices2510 == "Выбор по учетному номеру") {
      	data$df2510_2 <- data$df2510[data$df2510$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2510 == "Выбор вида объекта учета") {
      	data$df2510_2 <- data$df2510[data$df2510$"Вид объекта учета" == input$text, ]
    } else if (!is.null(input$dates2510) && !any(is.na(input$dates2510)) && !is.null(input$text) && input$choices2510 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2510[1L])
      	to=as.Date(input$dates2510[2L])
      	if (from>to) to = from
      	selectdates2510_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2510_2 <- data$df2510[as.Date(data$df2510$"Дата операции") %in% selectdates2510_2 & data$df2510$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2510) && !any(is.na(input$dates2510)) && !is.null(input$text) && input$choices2510 == "Выбор по дате операции и виду объекта учета") {
     	from=as.Date(input$dates2510[1L])
      	to=as.Date(input$dates2510[2L])
      	if (from>to) to = from
      	selectdates2510_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2510_2 <- data$df2510[as.Date(data$df2510$"Дата операции") %in% selectdates2510_3 & data$df2510$"Вид объекта учета" == input$text, ]
    } else {
        selectdates2510_4 <- unique(data$df2510$"Дата операции")
        data$df2510_2 <- data$df2510[data$df2510$"Дата операции" %in% selectdates2510_4, ]
    }
   }
  })

