#2771

observeEvent(input$dates2771, {
    start <- ymd(input$dates2771[[1]])
    end <- ymd(input$dates2771[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2771", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2771[[1]]
      r$end <- input$dates2771[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2771",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
   }, ignoreInit = TRUE)

  observe({
    if (!is.null(input$table2771Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2771 <- hot_to_r(input$table2771Item1)

    if (!any(is.na(input$dates2771)) && input$choices2771 == "Выбор по дате операции") {
     	from=as.Date(input$dates2771[1L])
      	to=as.Date(input$dates2771[2L])
      	if (from>to) to = from
      	selectdates2771_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2771_2 <- data$df2771[as.Date(data$df2771$"Дата операции") %in% selectdates2771_1, ]
    } else if (!is.null(input$text2771) && input$choices2771 == "Выбор по учетному номеру") {
      	data$df2771_2 <- data$df2771[data$df2771$"Учетный номер" == input$text2771, ]
    } else if (!is.null(input$dates2771) && !any(is.na(input$dates2771)) && !is.null(input$text2771) && input$choices2771 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2771[1L])
      	to=as.Date(input$dates2771[2L])
      	if (from>to) to = from
      	selectdates2771_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2771_2 <- data$df2771[as.Date(data$df2771$"Дата операции") %in% selectdates2771_2 & data$df2771$"Учетный номер" == input$text2771, ]
    } else {
        selectdates2771_4 <- unique(data$df2771$"Дата операции")
        data$df2771_2 <- data$df2771[data$df2771$"Дата операции" %in% selectdates2771_4, ]
    }
   }
  })  

  output$table2771Item1 <- renderRHandsontable({

	data$df2771[, `Конечное сальдо амортизации` := `Начальное сальдо амортизации` - `Дебет` + `Кредит`]

    rhandsontable(data$df2771, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
      hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })
  
  output$nested_ui2771 <- renderUI({
    if (input$choices2771 == "Выбор по дате операции") {
      	dateRangeInput("dates2771", "Выберите период времени:",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2771 == "Выбор по учетному номеру") {
      	textInput("text2771", "Укажите Учетный номер:")
    } else if (input$choices2771 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2771", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text2771", "Укажите Учетный номер:")
      )
    }
  })

  output$table2771Item2 <- renderRHandsontable({
    rhandsontable(data$df2771_2, colWidths = 150, height = 500, readOnly=TRUE,  
		contextMenu = FALSE, manualColumnResize = TRUE, dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date")
  })

  output$download_df2771 <- downloadHandler(
