#2810

observeEvent(input$dates2810.1, {
    start <- ymd(input$dates2810.1[[1]])
    end <- ymd(input$dates2810.1[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2810.1", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2810.1[[1]]
      r$end <- input$dates2810.1[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2810.1",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
  }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2810.1Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2810.1_1 <- hot_to_r(input$table2810.1Item1)

    if (!any(is.na(input$dates2810.1)) && input$choices2810.1 == "Выбор по дате операции") {
     	from=as.Date(input$dates2810.1[1L])
      	to=as.Date(input$dates2810.1[2L])
      	if (from>to) to = from
      	selectdates2810.1_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2810.1_2 <- data$df2810.1_1[as.Date(data$df2810.1_1$"Дата операции") %in% selectdates2810.1_1, ]
    } else if (!is.null(input$text) && input$choices2810.1 == "Выбор по учетному номеру") {
      	data$df2810.1_2 <- data$df2810.1_1[data$df2810.1_1$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2810.1) && !any(is.na(input$dates2810.1)) && !is.null(input$text) && input$choices2810.1 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2810.1[1L])
      	to=as.Date(input$dates2810.1[2L])
      	if (from>to) to = from
      	selectdates2810.1_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2810.1_2 <- data$df2810.1_1[as.Date(data$df2810.1_1$"Дата операции") %in% selectdates2810.1_2 & data$df2810.1_1$"Учетный номер" == input$text, ]
    } else {
        selectdates2810.1_4 <- unique(data$df2810.1_1$"Дата операции")
        data$df2810.1_2 <- data$df2810.1_1[data$df2810.1_1$"Дата операции" %in% selectdates2810.1_4, ]
    }
   }
  })  

  output$table2810.1Item1 <- renderRHandsontable({

    data$df2810.1_1[, `Сальдо конечное` := data$df2810.1_1[[5]] + data$df2810.1_1[[6]] - data$df2810.1_1[[7]]]

    rhandsontable(data$df2810.1_1, colWidths = 150, height = 500, 
                 allowInvalid=FALSE, fixedColumnsLeft = 2, manualColumnResize = TRUE,
                 contextMenu = TRUE, language = 'ru-RU', dragColumns = FALSE) |>
      hot_col(1, dateFormat = "YYYY-MM-DD", type = "date") |>
      hot_col(2, readOnly = TRUE) |>
      hot_col("Пользователь", readOnly = TRUE) |> hot_col("Время проводки", readOnly = TRUE)
  })

  output$nested_ui2810.1 <- renderUI({
    if (input$choices2810.1 == "Выбор по дате операции") {
      	dateRangeInput("dates2810.1", "Выберите период времени:",
                     start = Sys.Date(), end = Sys.Date(), separator = "-")
    } else if (input$choices2810.1 == "Выбор по учетному номеру") {
      	textInput("text", "Укажите Учетный номер:")
    } else if (input$choices2810.1 == "Выбор по дате операции и учетному номеру") {
      fluidRow(
       	dateRangeInput("dates2810.1", "Выберите период времени:",
                       start = Sys.Date(), end = Sys.Date(), separator = "-"),
        textInput("text", "Укажите Учетный номер:")
      )
    }
  })

