#2990

observeEvent(input$dates2990, {
    start <- ymd(input$dates2990[[1]])
    end <- ymd(input$dates2990[[2]])

 tryCatch({  
  if (start > end) {
    shinyalert("Ошибка при вводе: конечная дата предшествует начальной дате", type = "error")
    updateDateRangeInput(
      session, 
      "dates2990", 
        start = r$start,
        end = r$end
      )
    } else {
      r$start <- input$dates2990[[1]]
      r$end <- input$dates2990[[2]]
    }
   }, error = function(e) {
      updateDateRangeInput(session,
                           "dates2990",
                           start = ymd(Sys.Date()),
                           end = ymd(Sys.Date()))
      shinyalert("Диапазон дат не может быть пустым! Переход на текущую дату.",
                 type = "error")
    })
  }, ignoreInit = TRUE)

  observe({ 
    if (!is.null(input$table2990Item1)) {
      if (!r$user_authenticated) {
        update_auth_status("Для внесения изменений необходимо авторизоваться!", "warning")
        return()
      }
      
      data$df2990 <- hot_to_r(input$table2990Item1)

    if (!any(is.na(input$dates2990)) && input$choices2990 == "Выбор по дате операции") {
     	from=as.Date(input$dates2990[1L])
      	to=as.Date(input$dates2990[2L])
      	if (from>to) to = from
      	selectdates2990_1 <- seq.Date(from=from, to=to, by = "day")
      	data$df2990_2 <- data$df2990[as.Date(data$df2990$"Дата операции") %in% selectdates2990_1, ]
    } else if (!is.null(input$text) && input$choices2990 == "Выбор по учетному номеру") {
      	data$df2990_2 <- data$df2990[data$df2990$"Учетный номер" == input$text, ]
    } else if (!is.null(input$text) && input$choices2990 == "Выбор по идентификации прочих долгосрочных активов") {
      	data$df2990_2 <- data$df2990[data$df2990$"Вид или другая идентификация прочих долгосрочных активов" == input$text, ]
    } else if (!is.null(input$dates2990) && !any(is.na(input$dates2990)) && !is.null(input$text) && input$choices2990 == "Выбор по дате операции и учетному номеру") {
     	from=as.Date(input$dates2990[1L])
      	to=as.Date(input$dates2990[2L])
      	if (from>to) to = from
      	selectdates2990_2 <- seq.Date(from=from, to=to, by = "day")
      	data$df2990_2 <- data$df2990[as.Date(data$df2990$"Дата операции") %in% selectdates2990_2 & data$df2990$"Учетный номер" == input$text, ]
    } else if (!is.null(input$dates2990) && !any(is.na(input$dates2990)) && !is.null(input$text) && input$choices2990 == "Выбор по дате операции и идентификации прочих долгосрочных активов") {
     	from=as.Date(input$dates2990[1L])
      	to=as.Date(input$dates2990[2L])
      	if (from>to) to = from
      	selectdates2990_3 <- seq.Date(from=from, to=to, by = "day")
      	data$df2990_2 <- data$df2990[as.Date(data$df2990$"Дата операции") %in% selectdates2990_3 & data$df2990$"Вид или другая идентификация прочих долгосрочных активов" == input$text, ]
    } else {
        selectdates2990_4 <- unique(data$df2990$"Дата операции")
        data$df2990_2 <- data$df2990[data$df2990$"Дата операции" %in% selectdates2990_4, ]
    }
   }
  })  

